from taf.internal.sw.neat.client.site_manage.v1.apis.tags.edgedcs_api import EdgedcsApi
from taf.internal.sw.neat.client.site_manage.v1.apis.tags.servers_api import ServersApi
from taf.internal.sw.neat.client.site_manage.v1.apis.tags.health_api import HealthApi
from taf.internal.sw.neat.client.site_manage.v1.api_client import ApiClient
from taf.internal.sw.neat.client.site_manage.v1.configuration import Configuration
from taf.sw.neat.httpclient.neat_uri import SiteManagementURI
from taf.sw.neat.httpclient.ApiClientLocal import ApiClientLocal
from taf.sw.neat.utils.get_return_data import get_return_data


class SiteManagementV1(object):
    def __init__(self, conn_details, access_token):
        self.conn_details = conn_details
        self.configuration = Configuration()
        self.configuration.verify_ssl = False
        self.configuration.host = conn_details.make_configuration_host(original_endpoint=self.configuration.get_host_from_settings(index=None))
        self.configuration.access_token = access_token
        api_client = ApiClient(configuration=self.configuration)
        self.api_client_local = ApiClientLocal(conn_details, access_token)

        self.edgedcs_api = EdgedcsApi(api_client)
        self.servers_api = ServersApi(api_client)
        self.health_api = HealthApi(api_client)

    def get_edgedc_resources(self, raw=True, timeout=60, **kwargs):
        query_params = {}
        for key, val in kwargs.items():
            query_params[key] = val
        res = self.edgedcs_api.edgedcs_get(query_params=query_params, skip_deserialization=raw, timeout=timeout)
        return get_return_data(res, raw=raw)

    def create_edgedc_by_json_plan(self, edgedc_plan, raw=True, timeout=60):
        headers = {'Content-Type': 'application/json'}
        response = self.api_client_local.send_post_request(uri=SiteManagementURI.edgedcs_uri, headers=headers,
                                                       json=edgedc_plan, raw=raw, timeout=timeout)
        return get_return_data(response, raw=raw)["data"]

    def create_edgedc_by_yaml_plan(self, edgedc_plan, raw=False, timeout=60):
        with open(edgedc_plan, 'rb') as f:
            files = {'file': (edgedc_plan, f, 'application/x-yaml')}
            resp = self.api_client_local.send_post_request(
                    uri=SiteManagementURI.edgedcs_uri + '?operation=create',
                    files=files,
                    raw=raw,
                    timeout=timeout
                )
        return resp["data"]

    def delete_edgedc_resource(self, edgedc_id, timeout=60):
        return self.edgedcs_api.edgedcs_edge_dc_id_delete(path_params={'edgeDcId': edgedc_id}, timeout=timeout)

    def start_workflow(self, edgedc_id, workflow_id, raw=True, operation='start-workflow', timeout=60):
        path_param = {'edgeDcId': edgedc_id}
        query_params = {'operation': operation, 'workflow-id': workflow_id}
        patch_body = {"data": {"type": "edgedcs", "id": edgedc_id}}
        resp = self.edgedcs_api.edgedcs_edge_dc_id_patch(
            path_params=path_param,
            query_params=query_params,
            body=patch_body,
            skip_deserialization=raw,
            timeout=timeout
        )
        return get_return_data(resp, raw=raw)["data"]

    def modify_edgedc_server_resource(self, server_id, raw=True, timeout=60, **kwargs):
        body = {
            "data": {
                "type": "servers",
                "id": server_id,
                "attributes": kwargs
            }
        }
        res = self.servers_api.servers_server_id_patch(path_params={"serverId":server_id}, body=body,
                                                       skip_deserialization=raw, timeout=timeout)
        return get_return_data(res, raw=raw)["data"]

    def modify_edgedc_resources(self, edgedc_id, raw=True, timeout=60, **kwargs):
        if not kwargs:
            raise ValueError("At least one parameter should be provided to update!")
        body = {"data":{
            "type":"edgedcs",
            "id":edgedc_id,
            "attributes": kwargs
            }
        }

        res = self.edgedcs_api.edgedcs_edge_dc_id_patch(path_params={"edgeDcId": edgedc_id}, body=body,
                                                        skip_deserialization=raw, timeout=timeout)
        return get_return_data(res, raw=raw)["data"]

    def set_edgedc_certificate(self, edgedc_id, cert_type, cert_id, raw=True, timeout=60):
        if cert_id:
            patch_attributes = {cert_type: {"caCertificateId": cert_id}}
        else:
            patch_attributes = {cert_type: {}}
        return self.modify_edgedc_resources(edgedc_id, raw=raw, timeout=timeout, **patch_attributes)

    def get_edgedc_manager_health(self, raw=True, timeout=60, **kwargs):
        query_params = {}
        for key, val in kwargs.items():
            query_params[key] = val
        res = self.health_api.admin_health_get(query_params=query_params, skip_deserialization=raw, timeout=timeout)
        return get_return_data(res, raw=raw)['data']

    def start_workflow_group(self, edgedc_id, workflow_names, timeout=60):
        if not isinstance(workflow_names, str):
            raise ValueError("Workflow Names must be a comma-separated string")
        uri = f"{SiteManagementURI.edgedcs_uri}/{edgedc_id}?operation=start-workflow-group&workflow-names={workflow_names}"
        body = {
            "data": {
                "id": edgedc_id,
                "type": "edgedcs",
                "attributes": {},
            }
        }
        headers = {"Content-Type": "application/merge-patch+json"}
        return self.api_client_local.send_patch_request(uri=uri, json=body, headers=headers, timeout=timeout)

    def set_cloud_intermediate_upgrade_sw_id(self, *, edgedc_id: str, sw_id: str, raw=True, timeout=60):
        patch_attributes = {
            "data": {
                "type": "edgedcs",
                "id": edgedc_id,
                "attributes": {
                    "cloudIntermediateUpgradeSwId": sw_id
                    }
            }
        }
        headers = {"Content-Type": "application/merge-patch+json"}
        return self.api_client_local.send_patch_request(uri=f"{SiteManagementURI.edgedcs_uri}/{edgedc_id}",
                                                        headers=headers, json=patch_attributes, raw=raw,
                                                        timeout=timeout)
